WITH combined_returns AS ( SELECT s.s_store_id, s.s_store_name, dr_sr.d_year AS return_year, SUM(sr.sr_net_loss) AS store_net_loss, COALESCE(SUM(wr.wr_net_loss), 0) AS web_net_loss, SUM(sr.sr_net_loss) + COALESCE(SUM(wr.wr_net_loss), 0) AS total_net_loss, SUM(sr.sr_return_quantity) + COALESCE(SUM(wr.wr_return_quantity), 0) AS total_return_qty, MAX(CASE WHEN p.p_discount_active = 'Y' THEN 'Discounted' ELSE 'Full Price' END) AS promo_status, MAX(i.i_current_price) AS max_price, MIN(i.i_current_price) AS min_price FROM store_returns sr JOIN date_dim dr_sr ON sr.sr_returned_date_sk = dr_sr.d_date_sk JOIN store s ON sr.sr_store_sk = s.s_store_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk JOIN household_demographics hd_sr ON sr.sr_hdemo_sk = hd_sr.hd_demo_sk JOIN reason r_sr ON sr.sr_reason_sk = r_sr.r_reason_sk LEFT JOIN web_returns wr ON sr.sr_item_sk = wr.wr_item_sk AND sr.sr_returned_date_sk = wr.wr_returned_date_sk LEFT JOIN date_dim dr_wr ON wr.wr_returned_date_sk = dr_wr.d_date_sk LEFT JOIN household_demographics hd_refunded ON wr.wr_refunded_hdemo_sk = hd_refunded.hd_demo_sk LEFT JOIN household_demographics hd_returning ON wr.wr_returning_hdemo_sk = hd_returning.hd_demo_sk LEFT JOIN reason r_wr ON wr.wr_reason_sk = r_wr.r_reason_sk JOIN promotion p ON p.p_item_sk = i.i_item_sk JOIN date_dim dr_p_start ON p.p_start_date_sk = dr_p_start.d_date_sk JOIN date_dim dr_p_end ON p.p_end_date_sk = dr_p_end.d_date_sk JOIN catalog_page cp ON cp.cp_start_date_sk = dr_sr.d_date_sk JOIN date_dim dr_cp_end ON cp.cp_end_date_sk = dr_cp_end.d_date_sk JOIN date_dim dr_store_closed ON s.s_closed_date_sk = dr_store_closed.d_date_sk WHERE dr_sr.d_year = 2001 AND s.s_state = 'CA' AND i.i_current_price > 100 AND p.p_discount_active = 'Y' AND hd_sr.hd_vehicle_count >= 1 GROUP BY s.s_store_sk, s.s_store_id, s.s_store_name, dr_sr.d_year ) SELECT s_store_id, s_store_name, return_year, total_net_loss, total_return_qty, promo_status, max_price, min_price, DENSE_RANK() OVER (PARTITION BY return_year ORDER BY total_net_loss DESC) AS loss_rank, CASE WHEN total_net_loss > 1000 THEN 'Very High Loss' ELSE 'Moderate Loss' END AS loss_category FROM combined_returns ORDER BY return_year, loss_rank LIMIT 100
